import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:yaqeen/core/text/arabic.dart';
import 'package:yaqeen/features/quran/domain/quran_data.dart';
import 'package:yaqeen/features/recite/domain/recitation.dart';

/// The shared recitation-match vectors (packages/contracts/fixtures/recitation-match, generated by
/// services/api/scripts/build-recitation-fixtures.ts and run by the API's TS port in
/// services/api/test/recordings.domain.test.ts). The app's [RecitationAligner] must mark every word the
/// same way, so the on-device pre-check and the server's AI check provably agree. Coverage, extra
/// ratio and verdict are derived here from the marks by the contract rules (rules.json).
const _dir = '../../packages/contracts/fixtures/recitation-match';

Object? _load(String name) => jsonDecode(File('$_dir/$name').readAsStringSync());

double _round(double x) => (x * 10000).round() / 10000;

void main() {
  final rules = (_load('rules.json')! as Map).cast<String, dynamic>();
  final t = (rules['thresholds'] as Map).cast<String, dynamic>();

  test('normalize.json: ArabicText.normalize and the word split agree', () {
    for (final v in (_load('normalize.json')! as List).cast<Map<String, dynamic>>()) {
      expect(ArabicText.normalize(v['input'] as String), v['output'], reason: v['input'] as String);
      expect(RecitationAligner.words(v['input'] as String), hasLength((v['keys'] as List).length));
    }
  });

  test('same.json: RecitationAligner.same agrees', () {
    for (final v in (_load('same.json')! as List).cast<Map<String, dynamic>>()) {
      expect(RecitationAligner.same(v['a'] as String, v['b'] as String), v['same'], reason: '${v['a']} / ${v['b']}');
    }
  });

  for (final c in (_load('cases.json')! as List).cast<Map<String, dynamic>>()) {
    test('case ${c['name']}', () {
      final surah = c['surah'] as int;
      final expected = [
        for (final e in (c['expected'] as List).cast<Map<String, dynamic>>()) (AyahRef(surah, e['ayah'] as int), e['text'] as String),
      ];
      final heardEntries = (c['heard'] as List).cast<Map<String, dynamic>>();
      final heard = heardEntries.map((h) => h['text'] as String).join(' ');
      final results = RecitationAligner.align(expected, heard);
      final marks = [for (final a in results) for (final w in a.words) w.mark.name];
      final result = (c['result'] as Map).cast<String, dynamic>();
      expect(marks, result['marks'], reason: 'marks');

      // The contract's scores and verdict, from the marks.
      final n = marks.length;
      final ok = marks.where((m) => m == 'ok').length;
      final paired = marks.where((m) => m != 'skipped').length;
      final heardCount = RecitationAligner.words(heard).length;
      final coverage = n == 0 ? 0.0 : ok / n;
      final extra = heardCount == 0 ? 0.0 : (heardCount - paired) / heardCount;
      final duration = c['durationMs'] as int;
      final speech = duration <= 0 ? 0.0 : ((c['speechMs'] as int) / duration).clamp(0.0, 1.0);
      expect(_round(coverage), result['coverage'], reason: 'coverage');
      expect(_round(extra), result['extraRatio'], reason: 'extraRatio');
      expect(_round(speech), result['speech'], reason: 'speech');
      final String verdict;
      if (speech < (t['silenceSpeech'] as num)) {
        verdict = 'reject';
      } else if (heardCount == 0) {
        verdict = 'reject';
      } else if (coverage < (t['rejectCoverage'] as num)) {
        verdict = 'reject';
      } else if (coverage >= (t['approveCoverage'] as num) && speech >= (t['approveSpeech'] as num) && extra <= (t['maxExtraRatio'] as num)) {
        verdict = 'approve';
      } else {
        verdict = 'needs_review';
      }
      expect(verdict, result['verdict'], reason: 'verdict');
      // Karaoke entries exist exactly for the heard (ok/warn) words.
      expect((result['words'] as List).length, paired);
    });
  }
}
